<?php

namespace App\Support;

class PwaAssets
{
    public const ICON_192_B64 = '';
    public const ICON_512_B64 = '';

    public static function getIcon192(): string
    {
        $file = public_path('pwa-icon-192.png');
        if (file_exists($file)) {
            return file_get_contents($file);
        }
        $fileImg = public_path('images/pwa-icon-192.png');
        if (file_exists($fileImg)) {
            return file_get_contents($fileImg);
        }
        return base64_decode(self::ICON_192_B64);
    }

    public static function getIcon512(): string
    {
        $file = public_path('pwa-icon-512.png');
        if (file_exists($file)) {
            return file_get_contents($file);
        }
        $fileImg = public_path('images/pwa-icon-512.png');
        if (file_exists($fileImg)) {
            return file_get_contents($fileImg);
        }
        return base64_decode(self::ICON_512_B64);
    }

    public static function renderManifest(?string $firmSlug = null): \Illuminate\Http\JsonResponse
    {
        $firm = $firmSlug ? \App\Services\FirmRegistry::get(strtolower(trim($firmSlug))) : null;
        if (! $firm) {
            $firm = \App\Services\FirmRegistry::defaultFirm();
        }
        $slug = $firm['slug'] ?? 'rac';
        $shortName = $firm['short_code'] ?? ($firm['name'] ?? 'Practice ERP');
        $fullName = ($firm['name'] ?? 'DhakaWala ERP') . ' — Practice Workspace';
        $startUrl = $firmSlug ? url('/c/' . $slug . '/dashboard?pwa=1') : url('/dashboard?pwa=1');

        return response()->json([
            'id'               => $firmSlug ? ('/c/' . $slug . '/dashboard?pwa=1') : '/dashboard?pwa=1',
            'name'             => $fullName,
            'short_name'       => mb_substr($shortName, 0, 15) . ' ERP',
            'description'      => 'GPS Attendance, Conveyance Claims, Leave Passbook & Monthly Stipend App.',
            'start_url'        => $startUrl,
            'scope'            => '/',
            'display'          => 'standalone',
            'orientation'      => 'portrait-primary',
            'background_color' => '#17191F',
            'theme_color'      => '#17191F',
            'icons'            => [
                [
                    'src'     => url('/pwa-icon-192.png'),
                    'sizes'   => '192x192',
                    'type'    => 'image/png',
                    'purpose' => 'any',
                ],
                [
                    'src'     => url('/pwa-icon-192.png'),
                    'sizes'   => '192x192',
                    'type'    => 'image/png',
                    'purpose' => 'maskable',
                ],
                [
                    'src'     => url('/pwa-icon-512.png'),
                    'sizes'   => '512x512',
                    'type'    => 'image/png',
                    'purpose' => 'any',
                ],
                [
                    'src'     => url('/pwa-icon-512.png'),
                    'sizes'   => '512x512',
                    'type'    => 'image/png',
                    'purpose' => 'maskable',
                ],
                [
                    'src'     => url('/images/pwa-icon-192.png'),
                    'sizes'   => '192x192',
                    'type'    => 'image/png',
                    'purpose' => 'any',
                ],
                [
                    'src'     => url('/images/pwa-icon-512.png'),
                    'sizes'   => '512x512',
                    'type'    => 'image/png',
                    'purpose' => 'any',
                ],
            ],
        ], 200, [
            'Content-Type'  => 'application/manifest+json; charset=utf-8',
            'Cache-Control' => 'no-cache, no-store, must-revalidate',
        ]);
    }
}
